DROP TABLE IF EXISTS `cust_customer`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `cust_customer` (
  `id_customer` bigint unsigned NOT NULL AUTO_INCREMENT,
  `customer_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `customer_name` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `trade_name` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `parent_group` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `industry_category` varchar(150) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `tax_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'NPWP',
  `mr_ms` varchar(5) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Bapak/Ibu',
  `contact_name` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `default_address` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `default_area_id` bigint unsigned DEFAULT NULL COMMENT 'FK -> geo_city/geo_district (id wilayah)',
  `default_area_level` enum('CITY','DISTRICT','VILLAGE') COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Level rujukan default_area_id: CITY->geo_city.id_city | DISTRICT->geo_district.id_district | VILLAGE->geo_village.id_village',
  `postal_code` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Kode pos manual, prefill dari v_geo_full_address.postal_code saat pilih wilayah, tetap editable',
  `email` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `phone` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `website` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `customer_type` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT 'local' COMMENT 'local | import',
  `payment_term` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'FK -> fin_payment_term (menyusul)',
  `currency_code` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT 'IDR' COMMENT 'FK -> fin_currency.currency_code',
  `credit_limit` decimal(18,2) unsigned DEFAULT '0.00' COMMENT 'Batas piutang',
  `current_balance` decimal(18,2) unsigned DEFAULT '0.00' COMMENT 'Saldo piutang berjalan',
  `is_prospect` tinyint(1) NOT NULL DEFAULT '0' COMMENT '1=prospek (calon dari inkuiri) | 0=resmi',
  `is_active` tinyint(1) NOT NULL DEFAULT '1',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `created_by` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `updated_by` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `legacy_vendor_code` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Trace ke tm2old.mst_vendor.vendor_code — kunci idempotent engine migrasi, TIDAK dipakai user.',
  `nickname` varchar(10) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `alias_code` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `category` varchar(30) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Kategori tracking pembayaran (LANCAR/KURANG LANCAR/dst) — lihat cust_category',
  `is_blacklisted` tinyint(1) NOT NULL DEFAULT '0',
  `approval_status` enum('DRAFT','CREDIT_CHECK','APPROVED','BLOCKED') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'DRAFT',
  `phone_2` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `fax` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `tax_purchase_value` decimal(5,2) unsigned DEFAULT '0.00' COMMENT 'Tarif pajak pembelian (%)',
  `tax_service_value` decimal(5,2) unsigned DEFAULT '0.00' COMMENT 'Tarif pajak jasa (%)',
  `note` text COLLATE utf8mb4_unicode_ci,
  `primary_product` varchar(150) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `secondary_product` varchar(150) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `default_substrate` varchar(150) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `color_standard` varchar(150) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `proofing_method` varchar(150) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `artwork_approval` varchar(150) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `retained_sample` varchar(150) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `barcode_verification` varchar(150) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `finishing_preference` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `die_owner` varchar(150) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `packing_instruction` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `quality_notes` text COLLATE utf8mb4_unicode_ci,
  `sales_division_id` bigint unsigned DEFAULT NULL COMMENT 'SBU produksi utama pelanggan ini',
  `price_list_code` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `tax_profile` enum('PPN_11','EXEMPT') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'PPN_11',
  `credit_check_enabled` tinyint(1) NOT NULL DEFAULT '1',
  `credit_rating` enum('A','B','C') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'B' COMMENT 'A=Low Risk, B=Medium, C=High Risk',
  `tax_validated` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'NPWP diverifikasi manual oleh Finance',
  `kyc_status` enum('PENDING','APPROVED','REJECTED') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'PENDING',
  PRIMARY KEY (`id_customer`) USING BTREE,
  UNIQUE KEY `uq_customer_code` (`customer_code`) USING BTREE,
  UNIQUE KEY `cust_customer_legacy_vendor_code_unique` (`legacy_vendor_code`),
  KEY `idx_cust_area` (`default_area_id`) USING BTREE,
  KEY `cust_customer_payment_term_foreign` (`payment_term`),
  KEY `cust_customer_category_foreign` (`category`),
  KEY `cust_customer_sales_division_id_foreign` (`sales_division_id`),
  CONSTRAINT `cust_customer_category_foreign` FOREIGN KEY (`category`) REFERENCES `cust_category` (`category_code`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `cust_customer_payment_term_foreign` FOREIGN KEY (`payment_term`) REFERENCES `fin_payment_term` (`payment_term_code`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `cust_customer_sales_division_id_foreign` FOREIGN KEY (`sales_division_id`) REFERENCES `org_division` (`division_id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=895 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='Master customer (+prospek)';
/*!40101 SET character_set_client = @saved_cs_client */;

LOCK TABLES `cust_customer` WRITE;
/*!40000 ALTER TABLE `cust_customer` DISABLE KEYS */;
