DROP TABLE IF EXISTS `emp_attendance_log`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `emp_attendance_log` (
  `attendance_id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `employee_id` bigint unsigned NOT NULL,
  `attendance_date` date NOT NULL,
  `clock_in_at` datetime DEFAULT NULL COMMENT 'Scan masuk aktual dari mesin fingerprint',
  `clock_out_at` datetime DEFAULT NULL COMMENT 'Scan keluar aktual dari mesin fingerprint',
  `source` varchar(15) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'EXCEL_IMPORT' COMMENT 'EXCEL_IMPORT|MANUAL',
  `import_batch_ref` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `notes` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `created_by` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  `updated_by` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  PRIMARY KEY (`attendance_id`),
  UNIQUE KEY `uq_attendance_employee_date` (`employee_id`,`attendance_date`),
  KEY `idx_attendance_date` (`attendance_date`),
  CONSTRAINT `emp_attendance_log_employee_id_foreign` FOREIGN KEY (`employee_id`) REFERENCES `emp_employee` (`employee_id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

LOCK TABLES `emp_attendance_log` WRITE;
/*!40000 ALTER TABLE `emp_attendance_log` DISABLE KEYS */;
/*!40000 ALTER TABLE `emp_attendance_log` ENABLE KEYS */;
