DROP TABLE IF EXISTS `emp_education`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `emp_education` (
  `education_id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `employee_id` bigint unsigned NOT NULL,
  `education_type` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'SERTIFIKASI|SEMINAR|PELATIHAN|PENDIDIKAN_FORMAL',
  `activity_name` varchar(200) COLLATE utf8mb4_unicode_ci NOT NULL,
  `organizer` varchar(150) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `activity_date` date NOT NULL,
  `duration_days` smallint unsigned DEFAULT NULL,
  `cost` decimal(18,4) NOT NULL DEFAULT '0.0000',
  `funded_by` varchar(15) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'PERUSAHAAN|PRIBADI|SHARING',
  `certificate_path` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `valid_until` date DEFAULT NULL,
  `is_bonding` tinyint(1) NOT NULL DEFAULT '0',
  `bonding_note` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `uploaded_by_role` varchar(4) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'SELF' COMMENT 'SELF|HR',
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`education_id`),
  KEY `emp_education_employee_id_foreign` (`employee_id`),
  CONSTRAINT `emp_education_employee_id_foreign` FOREIGN KEY (`employee_id`) REFERENCES `emp_employee` (`employee_id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
