DROP TABLE IF EXISTS `emp_employee`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `emp_employee` (
  `employee_id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `legacy_employee_id` bigint unsigned DEFAULT NULL,
  `employee_code` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Auto: {company_code}-{seq 5 digit}, mis. TM-00001',
  `company_id` bigint unsigned NOT NULL,
  `position_id` bigint unsigned NOT NULL,
  `full_name` varchar(150) COLLATE utf8mb4_unicode_ci NOT NULL,
  `nickname` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `gender` varchar(1) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'L|P',
  `birth_place` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `birth_date` date DEFAULT NULL,
  `nik_ktp` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `npwp_number` varchar(30) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `religion` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `marital_status` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `phone` varchar(30) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `email_personal` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `village_id_ktp` bigint unsigned DEFAULT NULL COMMENT 'Logical -> tm2mst.geo_village',
  `address_detail_ktp` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `village_id_domisili` bigint unsigned DEFAULT NULL COMMENT 'NULL = sama dgn KTP',
  `address_detail_domisili` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `join_date` date DEFAULT NULL,
  `resign_date` date DEFAULT NULL,
  `resign_reason` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `photo_path` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `work_status` varchar(15) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'WORKING' COMMENT 'WORKING|DIRUMAHKAN|CUTI',
  `work_status_since` date DEFAULT NULL,
  `emergency_contact_name` varchar(150) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `emergency_contact_relation` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `emergency_contact_phone` varchar(30) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `default_machine_id` bigint unsigned DEFAULT NULL,
  `default_shift_id` bigint unsigned DEFAULT NULL,
  `is_active` tinyint(1) NOT NULL DEFAULT '1',
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `created_by` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `updated_by` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  PRIMARY KEY (`employee_id`),
  UNIQUE KEY `emp_employee_employee_code_unique` (`employee_code`),
  UNIQUE KEY `emp_employee_legacy_employee_id_unique` (`legacy_employee_id`),
  KEY `emp_employee_company_id_foreign` (`company_id`),
  KEY `emp_employee_position_id_foreign` (`position_id`),
  KEY `emp_employee_default_machine_id_foreign` (`default_machine_id`),
  KEY `emp_employee_default_shift_id_foreign` (`default_shift_id`),
  CONSTRAINT `emp_employee_company_id_foreign` FOREIGN KEY (`company_id`) REFERENCES `org_company` (`company_id`) ON DELETE RESTRICT,
  CONSTRAINT `emp_employee_default_machine_id_foreign` FOREIGN KEY (`default_machine_id`) REFERENCES `prod_machine` (`machine_id`) ON DELETE SET NULL,
  CONSTRAINT `emp_employee_default_shift_id_foreign` FOREIGN KEY (`default_shift_id`) REFERENCES `emp_shift` (`shift_id`) ON DELETE SET NULL,
  CONSTRAINT `emp_employee_position_id_foreign` FOREIGN KEY (`position_id`) REFERENCES `org_position` (`position_id`) ON DELETE RESTRICT
) ENGINE=InnoDB AUTO_INCREMENT=492 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
