CREATE TABLE `emp_shift_roster` (
  `roster_id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `batch_id` bigint unsigned DEFAULT NULL,
  `employee_id` bigint unsigned NOT NULL,
  `division_id` bigint unsigned NOT NULL,
  `machine_id` bigint unsigned DEFAULT NULL,
  `shift_id` bigint unsigned NOT NULL,
  `roster_date` date NOT NULL,
  `assigned_by_role` varchar(10) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'HR' COMMENT 'PPIC|HR',
  `is_overtime` tinyint(1) NOT NULL DEFAULT '0',
  `overtime_type` varchar(15) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'REGULER|HARI_MINGGU|HARI_BESAR',
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `created_by` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `updated_by` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  PRIMARY KEY (`roster_id`),
  UNIQUE KEY `uq_roster_exact` (`employee_id`,`roster_date`,`shift_id`,`machine_id`),
  KEY `emp_shift_roster_batch_id_foreign` (`batch_id`),
  KEY `emp_shift_roster_shift_id_foreign` (`shift_id`),
  KEY `emp_shift_roster_division_id_roster_date_index` (`division_id`,`roster_date`),
  KEY `emp_shift_roster_machine_id_shift_id_roster_date_index` (`machine_id`,`shift_id`,`roster_date`),
  CONSTRAINT `emp_shift_roster_batch_id_foreign` FOREIGN KEY (`batch_id`) REFERENCES `emp_shift_roster_batch` (`batch_id`) ON DELETE SET NULL,
  CONSTRAINT `emp_shift_roster_division_id_foreign` FOREIGN KEY (`division_id`) REFERENCES `org_division` (`division_id`) ON DELETE RESTRICT,
  CONSTRAINT `emp_shift_roster_employee_id_foreign` FOREIGN KEY (`employee_id`) REFERENCES `emp_employee` (`employee_id`) ON DELETE RESTRICT,
  CONSTRAINT `emp_shift_roster_machine_id_foreign` FOREIGN KEY (`machine_id`) REFERENCES `prod_machine` (`machine_id`) ON DELETE SET NULL,
  CONSTRAINT `emp_shift_roster_shift_id_foreign` FOREIGN KEY (`shift_id`) REFERENCES `emp_shift` (`shift_id`) ON DELETE RESTRICT
) ENGINE=InnoDB AUTO_INCREMENT=7 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
