  `ppic_reviewed_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`request_id`),
  KEY `emp_shift_swap_request_requester_employee_id_foreign` (`requester_employee_id`),
  KEY `emp_shift_swap_request_requester_roster_id_foreign` (`requester_roster_id`),
  KEY `emp_shift_swap_request_target_employee_id_foreign` (`target_employee_id`),
  KEY `emp_shift_swap_request_target_roster_id_foreign` (`target_roster_id`),
  CONSTRAINT `emp_shift_swap_request_requester_employee_id_foreign` FOREIGN KEY (`requester_employee_id`) REFERENCES `emp_employee` (`employee_id`) ON DELETE RESTRICT,
  CONSTRAINT `emp_shift_swap_request_requester_roster_id_foreign` FOREIGN KEY (`requester_roster_id`) REFERENCES `emp_shift_roster` (`roster_id`) ON DELETE RESTRICT,
  CONSTRAINT `emp_shift_swap_request_target_employee_id_foreign` FOREIGN KEY (`target_employee_id`) REFERENCES `emp_employee` (`employee_id`) ON DELETE RESTRICT,
  CONSTRAINT `emp_shift_swap_request_target_roster_id_foreign` FOREIGN KEY (`target_roster_id`) REFERENCES `emp_shift_roster` (`roster_id`) ON DELETE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
