DROP TABLE IF EXISTS `geo_country`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `geo_country` (
  `id_country` bigint unsigned NOT NULL AUTO_INCREMENT,
  `country_code` varchar(5) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Kode negara 2-huruf (ISO 3166-1 alpha-2), mis. ID',
  `iso_code` varchar(5) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Kode 3-huruf (ISO 3166-1 alpha-3), mis. IDN',
  `country_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Nama negara',
  `capital_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Ibu kota',
  `call_country_no` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Kode telepon internasional, mis. 62',
  `land_area_km2` decimal(20,2) unsigned DEFAULT NULL COMMENT 'Luas daratan (km2)',
  `currency_id` int unsigned DEFAULT NULL COMMENT 'FK -> fin_currency. Mata uang resmi negara (1 negara->1 currency)',
  `tax_percentage` decimal(10,4) DEFAULT NULL COMMENT 'Default tax negara (pindahan dari m_currency lama)',
  `is_active` tinyint(1) NOT NULL DEFAULT '1' COMMENT '1=aktif | 0=nonaktif',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `created_by` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `updated_by` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  PRIMARY KEY (`id_country`) USING BTREE,
  UNIQUE KEY `uq_country_name` (`country_name`) USING BTREE,
  UNIQUE KEY `uq_country_code` (`country_code`) USING BTREE,
  KEY `idx_country_currency` (`currency_id`) USING BTREE,
  CONSTRAINT `fk_country_currency` FOREIGN KEY (`currency_id`) REFERENCES `fin_currency` (`id_currency`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=251 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='Master negara (Level 0 hierarki geo)';
/*!40101 SET character_set_client = @saved_cs_client */;

