  `hs_code` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Kode HS/tarif bea cukai, mis. 4810.13.00',
  `material_name` varchar(200) COLLATE utf8mb4_unicode_ci NOT NULL,
  `item_type` enum('MATERIAL','SERVICE','FREE_SAMPLE') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'MATERIAL',
  `category1` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `category2` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `category3` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `category4` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `category5` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `description` text COLLATE utf8mb4_unicode_ci,
  `brand` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `color` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `gram_weight` int unsigned DEFAULT '0',
  `cm_length` decimal(12,4) unsigned DEFAULT '0.0000',
  `cm_width` decimal(12,4) unsigned DEFAULT '0.0000',
  `mm_thickness` decimal(12,4) unsigned DEFAULT '0.0000',
  `specification` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `qc_required` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Wajib inspeksi QC saat penerimaan (nyambung ke pv_line.qc_quality_status)',
  `shelf_life_days` smallint unsigned DEFAULT NULL COMMENT 'Masa simpan (hari), NULL = tak terbatas',
  `moisture_pct` decimal(5,2) DEFAULT NULL COMMENT 'Batas kelembaban standar (%)',
  `uom_stock` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'LOGICAL -> tm2mst.uom_unit.uom_code',
  `uom_purchase` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'LOGICAL -> tm2mst.uom_unit.uom_code',
  `purchasable` tinyint unsigned NOT NULL DEFAULT '1',
  `uom_usage` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'LOGICAL -> tm2mst.uom_unit.uom_code',
  `conversion_to_stock` decimal(20,6) unsigned DEFAULT '1.000000',
  `conversion_to_usage` decimal(20,6) unsigned DEFAULT NULL,
  `suggest_supplier_id` bigint unsigned DEFAULT NULL COMMENT 'LOGICAL -> tm2mst.sup_supplier.id_supplier',
  `tol_purchase` decimal(5,2) DEFAULT NULL COMMENT 'toleransi pembelian % - dipakai PROC_TIER_2 §A-4.3',
  `lead_time_days` smallint unsigned DEFAULT NULL COMMENT 'Estimasi lead time pengadaan (hari)',
  `purchase_tax_code` varchar(10) COLLATE utf8mb4_unicode_ci DEFAULT 'PPN' COMMENT 'PPN atau NON_PPN -- pajak masukan default item ini',
  `free_note` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `min_stock` decimal(20,4) unsigned DEFAULT '0.0000',
  `safety_stock` decimal(20,4) unsigned DEFAULT NULL,
  `reorder_point` decimal(20,4) unsigned DEFAULT NULL,
  `max_stock` decimal(20,4) unsigned DEFAULT NULL,
  `cur_stock` decimal(20,4) DEFAULT NULL,
  `is_active` tinyint unsigned DEFAULT '1',
  `avg_unitprice` decimal(30,5) DEFAULT NULL,
  `last_unitprice` decimal(30,5) DEFAULT NULL,
  `def_location_id` bigint unsigned DEFAULT NULL,
  `costing_method` enum('AVG','FIFO','LIFO','STANDARD') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'AVG' COMMENT 'Metode harga perolehan PER ITEM - STANDARD = harga tetap',
  `valuation_class` varchar(30) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Label klasifikasi laporan SAJA (bukan penentu akun), mis. "Raw Material - Kertas"',
  `is_fx_sensitive` tinyint(1) NOT NULL DEFAULT '0' COMMENT '1 = harga mengikuti kurs, tampilkan peringatan di PR/PQ',
  `prefix5_id` int unsigned DEFAULT NULL COMMENT 'FK doc_rmprefix5.idprefix - sumber kebenaran baru pembentuk material_code',
  `create_log` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `update_log` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `create_by` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `update_by` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `old_item_code` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `old_item_name` varchar(250) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `stock_asset_account_id` bigint unsigned DEFAULT NULL COMMENT 'LOGICAL -> tm2acc.fin_account (is_postable=1) - akun aset persediaan default item ini',
  `cogs_account_id` bigint unsigned DEFAULT NULL COMMENT 'LOGICAL -> tm2acc.fin_account - akun HPP/beban saat pemakaian',
  `gr_ir_account_id` bigint unsigned DEFAULT NULL COMMENT 'LOGICAL -> tm2acc.fin_account - akun kliring GR/IR (barang diterima, faktur belum masuk)',
  `cost_center_id` bigint unsigned DEFAULT NULL COMMENT 'LOGICAL -> tm2acc.fin_cost_center.cc_id - default cost center pemakaian',
  `profit_center_id` bigint unsigned DEFAULT NULL COMMENT 'LOGICAL -> tm2acc.fin_profit_center.pc_id - dimensi profit center',
  PRIMARY KEY (`material_id`),
  UNIQUE KEY `m_raw_material_material_code_unique` (`material_code`),
  KEY `m_raw_material_item_type_index` (`item_type`),
  KEY `m_raw_material_category1_index` (`category1`),
  KEY `m_raw_material_is_active_index` (`is_active`),
  KEY `m_raw_material_prefix5_id_foreign` (`prefix5_id`),
  CONSTRAINT `m_raw_material_prefix5_id_foreign` FOREIGN KEY (`prefix5_id`) REFERENCES `doc_rmprefix5` (`idprefix`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=5895 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

