  `qty_limit_min` decimal(12,2) unsigned DEFAULT '0.00',
  `qty_limit_max` decimal(12,2) unsigned DEFAULT '0.00',
  `cm_length` decimal(12,4) unsigned DEFAULT '0.0000',
  `cm_width` decimal(12,4) unsigned DEFAULT '0.0000',
  `cm_height` decimal(12,4) unsigned DEFAULT '0.0000',
  `min_stock` decimal(20,4) unsigned DEFAULT '0.0000',
  `max_stock` decimal(20,4) unsigned DEFAULT NULL,
  `cur_stock` decimal(20,4) DEFAULT '0.0000',
  `default_selling_price` decimal(10,2) unsigned DEFAULT '0.00',
  `minimum_selling_price` decimal(10,2) unsigned DEFAULT '0.00',
  `is_confirmed` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'ex stat_confirm',
  `card_status` varchar(15) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'DRAFT' COMMENT 'DRAFT|APPROVED — status Master Card',
  `is_active` tinyint(1) NOT NULL DEFAULT '1',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `created_by` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `updated_by` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `stock_asset_account_id` bigint unsigned DEFAULT NULL COMMENT 'LOGICAL -> tm2acc.fin_account (Persediaan Barang Jadi)',
  `cogs_account_id` bigint unsigned DEFAULT NULL COMMENT 'LOGICAL -> tm2acc.fin_account (HPP saat kirim/DO)',
  `cost_center_id` bigint unsigned DEFAULT NULL COMMENT 'LOGICAL -> tm2acc.fin_cost_center',
  `profit_center_id` bigint unsigned DEFAULT NULL COMMENT 'LOGICAL -> tm2acc.fin_cost_center (dipakai sbg profit center)',
  PRIMARY KEY (`id_product`) USING BTREE,
  UNIQUE KEY `uq_product_code` (`product_code`) USING BTREE,
  KEY `idx_prod_customer` (`customer_id`) USING BTREE,
  KEY `idx_prod_category` (`category_id`) USING BTREE,
  KEY `idx_prod_design` (`design_no`),
  CONSTRAINT `fk_prod_category` FOREIGN KEY (`category_id`) REFERENCES `prod_category` (`id_category`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `fk_prod_customer` FOREIGN KEY (`customer_id`) REFERENCES `cust_customer` (`id_customer`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=6 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='Header produk baku. Sumber snapshot RECALC/REVISE';
