/*!40000 ALTER TABLE `prod_type` ENABLE KEYS */;
UNLOCK TABLES;
DROP TABLE IF EXISTS `prod_type_param`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `prod_type_param` (
  `id_type_param` bigint unsigned NOT NULL AUTO_INCREMENT,
  `type_code` varchar(30) COLLATE utf8mb4_unicode_ci NOT NULL,
  `param_key` varchar(40) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'ex column_name — variabel DSL',
  `param_label` varchar(60) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `unit` varchar(10) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'mm, deg, pcs, %, x',
  `param_type` varchar(10) COLLATE utf8mb4_unicode_ci DEFAULT 'NUM' COMMENT 'NUM | ENUM',
  `option_json` json DEFAULT NULL,
  `is_required` tinyint(1) NOT NULL DEFAULT '0',
  `default_value` decimal(10,2) DEFAULT NULL,
  `default_str` varchar(60) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `min_value` decimal(10,2) DEFAULT NULL,
  `max_value` decimal(10,2) DEFAULT NULL,
  `seq` smallint unsigned NOT NULL DEFAULT '1',
  `is_active` tinyint(1) NOT NULL DEFAULT '1',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id_type_param`) USING BTREE,
  UNIQUE KEY `uq_tparam_type_key` (`type_code`,`param_key`) USING BTREE,
  KEY `idx_tparam_type` (`type_code`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=302 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Parameter dimensi per tipe (NUM/ENUM)';
/*!40101 SET character_set_client = @saved_cs_client */;

