UNLOCK TABLES;
DROP TABLE IF EXISTS `prod_type_size`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `prod_type_size` (
  `id_type_size` bigint unsigned NOT NULL AUTO_INCREMENT,
  `type_code` varchar(30) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'FK -> prod_type',
  `size_code` varchar(40) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Kode ukuran pasaran',
  `size_label` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Label, mis. "Small 8x5x2 cm"',
  `sort_order` smallint NOT NULL DEFAULT '999',
  `is_active` tinyint(1) NOT NULL DEFAULT '1',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `created_by` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `updated_by` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  PRIMARY KEY (`id_type_size`) USING BTREE,
  KEY `idx_tsize_type` (`type_code`) USING BTREE,
  CONSTRAINT `fk_tsize_type` FOREIGN KEY (`type_code`) REFERENCES `prod_type` (`type_code`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=84 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Ukuran pasaran per tipe (dropdown auto-fill dimensi)';
/*!40101 SET character_set_client = @saved_cs_client */;

LOCK TABLES `prod_type_size` WRITE;
