/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `sup_supplier` (
  `id_supplier` bigint unsigned NOT NULL AUTO_INCREMENT,
  `supplier_code` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `supplier_name` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `nickname` varchar(10) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `alias_code` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `category` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Kategori jenis supplier (ATK/BAHAN BAKU/JASA/dst) — lihat sup_category',
  `is_subcon` tinyint(1) NOT NULL DEFAULT '0',
  `contact_name` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `default_address` text COLLATE utf8mb4_unicode_ci,
  `default_area_id` bigint unsigned DEFAULT NULL COMMENT 'FK logis -> geo_city/geo_district/geo_village, level di default_area_level',
  `default_area_level` enum('CITY','DISTRICT','VILLAGE') COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `postal_code` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `email` varchar(150) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `phone` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `phone_2` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `fax` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `website` varchar(150) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `payment_term` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'FK -> fin_payment_term (menyusul), teks bebas untuk sekarang',
  `tax_code` varchar(25) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `tax_purchase_value` decimal(5,2) unsigned DEFAULT '0.00',
  `tax_service_value` decimal(5,2) unsigned DEFAULT '0.00',
  `is_blacklisted` tinyint(1) NOT NULL DEFAULT '0',
  `note` text COLLATE utf8mb4_unicode_ci,
  `is_active` tinyint(1) NOT NULL DEFAULT '1',
  `legacy_vendor_code` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Trace ke tm2old.mst_vendor.vendor_code — kunci idempotent engine migrasi.',
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `created_by` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `updated_by` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  PRIMARY KEY (`id_supplier`),
  UNIQUE KEY `sup_supplier_supplier_code_unique` (`supplier_code`),
  UNIQUE KEY `sup_supplier_legacy_vendor_code_unique` (`legacy_vendor_code`),
  KEY `sup_supplier_payment_term_foreign` (`payment_term`),
  KEY `sup_supplier_category_foreign` (`category`),
  CONSTRAINT `sup_supplier_category_foreign` FOREIGN KEY (`category`) REFERENCES `sup_category` (`category_code`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `sup_supplier_payment_term_foreign` FOREIGN KEY (`payment_term`) REFERENCES `fin_payment_term` (`payment_term_code`) ON DELETE RESTRICT ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=284 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

