/*!40000 ALTER TABLE `sup_supplier` ENABLE KEYS */;
UNLOCK TABLES;
DROP TABLE IF EXISTS `sup_supplier_bank`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `sup_supplier_bank` (
  `id_supplier_bank` bigint unsigned NOT NULL AUTO_INCREMENT,
  `supplier_id` bigint unsigned NOT NULL,
  `bank_code` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `bank_account_no` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `bank_account_name` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `is_active` tinyint(1) NOT NULL DEFAULT '1',
  `legacy_vendor_bank_id` bigint unsigned DEFAULT NULL COMMENT 'Trace ke tm2old.mst_vendor_bank.vendor_bank_id',
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `created_by` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `updated_by` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  PRIMARY KEY (`id_supplier_bank`),
  UNIQUE KEY `sup_supplier_bank_legacy_vendor_bank_id_unique` (`legacy_vendor_bank_id`),
  KEY `sup_supplier_bank_supplier_id_foreign` (`supplier_id`),
  CONSTRAINT `sup_supplier_bank_supplier_id_foreign` FOREIGN KEY (`supplier_id`) REFERENCES `sup_supplier` (`id_supplier`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=84 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

LOCK TABLES `sup_supplier_bank` WRITE;
