/*!50001 CREATE ALGORITHM=UNDEFINED */
/*!50013 DEFINER=`backupadmin`@`localhost` SQL SECURITY DEFINER */
/*!50001 VIEW `v_geo_full_address` AS select `v`.`id_village` AS `id_village`,`d`.`id_district` AS `id_district`,`c`.`id_city` AS `id_city`,`r`.`id_region` AS `id_region`,`ct`.`id_country` AS `id_country`,concat_ws(', ',`v`.`village_name`,`d`.`district_name`,concat_ws(' ',`c`.`city_type`,`c`.`city_name`),`r`.`region_name`,`ct`.`country_name`) AS `full_label`,coalesce(`v`.`post_code`,`d`.`post_code`,`c`.`post_code`) AS `postal_code`,`ct`.`country_name` AS `country_name`,`r`.`region_name` AS `region_name`,`c`.`city_type` AS `city_type`,`c`.`city_name` AS `city_name`,`d`.`district_name` AS `district_name`,`v`.`village_name` AS `village_name` from ((((`geo_city` `c` join `geo_region` `r` on((`r`.`id_region` = `c`.`region_id`))) join `geo_country` `ct` on((`ct`.`id_country` = `r`.`country_id`))) left join `geo_district` `d` on((`d`.`city_id` = `c`.`id_city`))) left join `geo_village` `v` on((`v`.`district_id` = `d`.`id_district`))) */;
