/*!50001 SET collation_connection      = utf8mb4_0900_ai_ci */;
/*!50001 CREATE ALGORITHM=UNDEFINED */
/*!50013 DEFINER=`root`@`localhost` SQL SECURITY DEFINER */
/*!50001 VIEW `vw_master_card` AS select `p`.`id_product` AS `id_product`,`p`.`product_code` AS `kode_item`,`p`.`design_no` AS `no_desain`,`p`.`product_name` AS `nama_barang`,cast(`p`.`created_at` as date) AS `tanggal`,`c`.`customer_name` AS `nama_pelanggan`,`p`.`card_status` AS `card_status`,concat(`p`.`cm_length`,' x ',`p`.`cm_width`,' x ',`p`.`cm_height`,' cm') AS `dimensi`,`pt`.`dieline_ref` AS `kode_pisau`,`pt`.`joint_type` AS `bentuk_sambungan`,`pt`.`finishing` AS `jenis_finishing`,`pt`.`up_per_print` AS `isi_satu_cetakan`,concat(`pt`.`printsize_p`,' x ',`pt`.`printsize_l`,' cm') AS `ukuran_cetak`,`pt`.`pack_qty` AS `pack_qty`,(select group_concat(concat('U',`prod_part_ink`.`unit_no`,':',`prod_part_ink`.`ink_name`) order by `prod_part_ink`.`unit_no` ASC separator ' ') from `prod_part_ink` where ((`prod_part_ink`.`part_id` = `pt`.`id_part`) and (`prod_part_ink`.`pass_seq` = 1))) AS `warna_cs`,(select group_concat(concat('U',`prod_part_ink`.`unit_no`,':',`prod_part_ink`.`ink_name`) order by `prod_part_ink`.`unit_no` ASC separator ' ') from `prod_part_ink` where ((`prod_part_ink`.`part_id` = `pt`.`id_part`) and (`prod_part_ink`.`pass_seq` = 2))) AS `warna_ks`,(select count(0) from `prod_part_material` where (`prod_part_material`.`part_id` = `pt`.`id_part`)) AS `jml_layer`,(select group_concat(`prod_part_process`.`process_name` order by `prod_part_process`.`step_seq` ASC separator ' > ') from `prod_part_process` where (`prod_part_process`.`part_id` = `pt`.`id_part`)) AS `urutan_pekerjaan`,(select count(0) from `prod_mastercard_signoff` where ((`prod_mastercard_signoff`.`product_id` = `p`.`id_product`) and (`prod_mastercard_signoff`.`signed_at` is not null))) AS `signed_count` from ((`prod_product` `p` join `prod_part` `pt` on((`pt`.`product_id` = `p`.`id_product`))) left join `cust_customer` `c` on((`c`.`id_customer` = `p`.`customer_id`))) */;
